#!/bin/sh
set -eu

cd "$(CDPATH= cd "$(dirname "$0")/.." && pwd)"

usage() {
  printf "%s\n" "Usage: sh tools/run-tests.sh list | --allow-sut one CASE | --allow-sut group AREA | --allow-sut all" >&2
  exit 64
}
allow_sut=false
if [ "${1-}" = "--allow-sut" ]; then allow_sut=true; shift; fi
case "${1-}" in
  list)
    [ "$#" -eq 1 ] || usage
    printf '%s\n' 'login-success [login] Successful login'
    exit 0 ;;
  one|group) [ "$#" -eq 2 ] || usage ;;
  all) [ "$#" -eq 1 ] || usage ;;
  *) usage ;;
esac

require_sut() {
  [ "$allow_sut" = true ] || {
    printf "%s\n" "BLOCKED: approve external SUT access and any selected registration writes before using --allow-sut." >&2
    exit 77
  }
}

case "$1:${2-}" in
  'one:login-success')
    require_sut
    printf '%s\n' '+ gradle --offline test --tests '\''tests.LoginTest.successfulLoginTest'\'''
    exec gradle --offline test --tests 'tests.LoginTest.successfulLoginTest'
    ;;
  'group:login')
    require_sut
    printf '%s\n' '+ gradle --offline test --tests '\''tests.LoginTest'\'''
    exec gradle --offline test --tests 'tests.LoginTest'
    ;;
  'all:')
    require_sut
    printf '%s\n' '+ gradle --offline test'
    exec gradle --offline test
    ;;
  *) usage ;;
esac
#!/bin/sh
set -eu

cd "$(CDPATH= cd "$(dirname "$0")/.." && pwd)"

usage() { printf "%s\n" "Usage: sh tools/git.sh status|diff|check" >&2; exit 64; }
[ "$#" -eq 1 ] || usage
export GIT_OPTIONAL_LOCKS=0
case "$1" in
  status)
    printf '%s\n' '+ git --no-pager -c core.fsmonitor=false status --short -- .'
    git --no-pager -c core.fsmonitor=false status --short -- .
    ;;
  diff)
    printf '%s\n' '+ git --no-pager -c core.fsmonitor=false diff --no-ext-diff --no-textconv -- .'
    git --no-pager -c core.fsmonitor=false diff --no-ext-diff --no-textconv -- .
    printf '%s\n' '+ git --no-pager -c core.fsmonitor=false diff --cached --no-ext-diff --no-textconv -- .'
    git --no-pager -c core.fsmonitor=false diff --cached --no-ext-diff --no-textconv -- .
    ;;
  check)
    printf '%s\n' '+ git --no-pager -c core.fsmonitor=false diff --check --no-ext-diff --no-textconv -- .'
    git --no-pager -c core.fsmonitor=false diff --check --no-ext-diff --no-textconv -- .
    printf '%s\n' '+ git --no-pager -c core.fsmonitor=false diff --cached --check --no-ext-diff --no-textconv -- .'
    git --no-pager -c core.fsmonitor=false diff --cached --check --no-ext-diff --no-textconv -- .
    ;;
  *) usage ;;
esac
package tests;

import java.nio.file.Path;

import org.junit.jupiter.api.Test;

import static com.codeborne.selenide.Condition.text;
import static com.codeborne.selenide.Selenide.$;
import static com.codeborne.selenide.Selenide.open;

public class LoginTest {
    @Test
    void successfulLoginTest() {
        open(Path.of("login.html").toAbsolutePath().toUri().toString());
        $("[data-testid=login-input]").setValue("user1");
        $("[data-testid=password-input]").setValue("password1");
        $("[data-testid=submit-button]").click();
        $("[data-testid=authorized-banner]").shouldHave(text("Hello, user1!"));
    }
}
plugins {
    id 'java-library'
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
